use serial_cli::script::ScriptManager;
use serial_cli::serial_core::{PortManager, VirtualSerialPair};
use serial_cli::state_factory::CoreManagers;
use std::collections::HashMap;
use std::path::PathBuf;
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::Arc;
use tokio::sync::{Mutex, RwLock};
use tokio::task::JoinHandle;
use tokio_util::sync::CancellationToken;

/// Per-port statistics tracked by the backend
pub struct PortStatsTracker {
    /// Bytes received (RX)
    pub bytes_received: Arc<AtomicU64>,
    /// Bytes sent (TX)
    pub bytes_sent: Arc<AtomicU64>,
    /// Packets received (RX event count)
    pub packets_received: Arc<AtomicU64>,
    /// Packets sent (TX event count)
    pub packets_sent: Arc<AtomicU64>,
    /// Last activity timestamp (Unix millis)
    pub last_activity: Arc<AtomicU64>,
}

impl PortStatsTracker {
    pub fn new() -> Self {
        Self {
            bytes_received: Arc::new(AtomicU64::new(0)),
            bytes_sent: Arc::new(AtomicU64::new(0)),
            packets_received: Arc::new(AtomicU64::new(0)),
            packets_sent: Arc::new(AtomicU64::new(0)),
            last_activity: Arc::new(AtomicU64::new(0)),
        }
    }

    pub fn snapshot(&self) -> (u64, u64, u64, u64, u64) {
        (
            self.bytes_received.load(Ordering::Relaxed),
            self.bytes_sent.load(Ordering::Relaxed),
            self.packets_received.load(Ordering::Relaxed),
            self.packets_sent.load(Ordering::Relaxed),
            self.last_activity.load(Ordering::Relaxed),
        )
    }
}

impl Default for PortStatsTracker {
    fn default() -> Self {
        Self::new()
    }
}

/// Data sniffer for monitoring serial port data
pub struct DataSniffer {
    /// Async event loop task (receives data from channel, emits Tauri events)
    pub task_handle: JoinHandle<()>,
    /// Blocking read loop task (reads from serial port, sends through channel)
    pub read_task_handle: JoinHandle<()>,
    /// Shared stop flag checked by both tasks
    pub stop_flag: Arc<std::sync::atomic::AtomicBool>,
    /// Statistics for this port
    #[allow(dead_code)]
    pub stats: Arc<PortStatsTracker>,
}

/// Global application state shared across all Tauri commands
#[derive(Clone)]
pub struct AppState {
    /// Serial port manager
    pub port_manager: Arc<Mutex<PortManager>>,
    /// Unified script manager (replaces protocol lifecycle)
    pub script_manager: Arc<Mutex<ScriptManager>>,
